Set<String> hashSet = new HashSet<>();
Set<String> linkedSet = new LinkedHashSet<>();
Set<String> treeSet = new TreeSet<>();

for (var s : List.of(hashSet, linkedSet, treeSet)) {
    s.add("CUR3001"); s.add("SAV2001"); s.add("FD4001");
}

hashSet;    // {SAV2001, FD4001, CUR3001} — random (hash-based)
linkedSet;  // {CUR3001, SAV2001, FD4001} — insertion order!
treeSet;    // {CUR3001, FD4001, SAV2001} — sorted!

// TreeSet extra: NavigableSet
TreeSet<String> nav = new TreeSet<>(treeSet);
nav.first();             // "CUR3001"
nav.last();              // "SAV2001"
nav.floor("EEE");        // "CUR3001" (≤ EEE)
nav.ceiling("EEE");      // "FD4001" (≥ EEE)
nav.subSet("CUR3001", "SAV2001"); // {CUR3001, FD4001}
nav.headSet("FD4001");   // {CUR3001} (before FD4001)
nav.tailSet("FD4001");   // {FD4001, SAV2001} (from FD4001 onwards)
```

