package com.bank.setcompare;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class SetVariantsTest {

    @Test
    void hashSet_unordered() {
        Set<String> set = new HashSet<>();
        set.add("CUR3001"); set.add("SAV2001"); set.add("FD4001");
        assertThat(set).containsExactlyInAnyOrder("CUR3001", "SAV2001", "FD4001");
    }

    @Test
    void linkedHashSet_insertionOrder() {
        Set<String> set = new LinkedHashSet<>();
        set.add("CUR3001"); set.add("SAV2001"); set.add("FD4001");
        assertThat(set).containsExactly("CUR3001", "SAV2001", "FD4001");
    }

    @Test
    void treeSet_sortedOrder() {
        Set<String> set = new TreeSet<>();
        set.add("CUR3001"); set.add("SAV2001"); set.add("FD4001");
        assertThat(set).containsExactly("CUR3001", "FD4001", "SAV2001");
    }

    @Test
    void treeSet_navigable() {
        TreeSet<Integer> balances = new TreeSet<>(List.of(10000, 50000, 75000, 120000));
        assertThat(balances.floor(60000)).isEqualTo(50000);     // ≤ 60K
        assertThat(balances.ceiling(60000)).isEqualTo(75000);   // ≥ 60K
        assertThat(balances.headSet(75000)).containsExactly(10000, 50000);
    }

    @Test
    void allRejectDuplicates() {
        for (Set<String> set : List.of(new HashSet<>(), new LinkedHashSet<>(), new TreeSet<>())) {
            set.add("SAV2001");
            boolean added = set.add("SAV2001");  // duplicate!
            assertThat(added).isFalse();
            assertThat(set).hasSize(1);
        }
    }
}
