  // all Sets wrap corresponding Map
  interface Set<E> { boolean add(E); boolean contains(E); }

  class HashSet<E>        { HashMap<E,Object> map; }       // O(1)
  class LinkedHashSet<E>  { LinkedHashMap<E,Object> map; } // order
  class TreeSet<E>        { TreeMap<E,Object> map; }       // sorted

  static final Object PRESENT = new Object();
  boolean add(E e){ return map.put(e,PRESENT)==null; }
  boolean contains(E e){ return map.containsKey(e); }

  // TreeSet adds NavigableSet:
  //   floor(e), ceiling(e), subSet(a,b),
  //   headSet(e), tailSet(e), first(), last()
  // ConcurrentHashMap.newKeySet() → thread-safe
